void panel_cholesky_(
        torch::Tensor input,
        torch::Tensor factor,
        torch::Tensor info,
        torch::Tensor workspace) {
    TORCH_CHECK(input.is_cuda() && factor.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(input.scalar_type() == at::kFloat &&
                factor.scalar_type() == at::kFloat,
                "FP32 tensors required");
    TORCH_CHECK(input.dim() == 3 && factor.dim() == 3 &&
                input.sizes() == factor.sizes() &&
                input.size(0) == 1 && input.size(1) == 4096 &&
                input.stride(2) == 1 && factor.stride(1) == 1 &&
                factor.stride(2) == 4096,
                "compatible 4096-square panel buffers required");
    TORCH_CHECK(info.is_cuda() && info.scalar_type() == at::kInt &&
                info.numel() == 1, "invalid panel info tensor");
    TORCH_CHECK(workspace.is_cuda() &&
                workspace.scalar_type() == at::kFloat,
                "invalid panel workspace tensor");
    copy_panel_to_factor_cuda(input, factor);
    auto handle = at::cuda::getCurrentCUDASolverDnHandle();
    check_cusolver(
        cusolverDnSetMathMode(handle, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
        "cusolverDnSetMathMode");
    check_cusolver(
        cusolverDnSpotrf(
            handle, CUBLAS_FILL_MODE_LOWER, 4096,
            factor.data_ptr<float>(), 4096,
            workspace.data_ptr<float>(), workspace.numel(),
            info.data_ptr<int>()),
        "panel cusolverDnSpotrf");
}

void batch_factor_gather_(
